INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.SORT_OBJECTS', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES', 'mathematics', 1, 'Sort objects according to similar attributes', ARRAY['MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.a']::text[], 'The child sorts a mixed collection into groups by one attribute (colour, size, shape, use or texture), says the rule used, and finds the object that does not belong in a group.', '["which one does not belong","sort into groups","what is the sorting rule","which group does this go in"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G1_PRENUMBER']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.MATCH_OBJECTS', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES', 'mathematics', 1, 'Match objects with similar attributes', ARRAY['MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.b']::text[], 'The child pairs objects that share an attribute (a shoe with a shoe, a big stone with a big stone, things used together such as a cup and a saucer), and says why they match.', '["match the pairs","which one goes with this","why do these match","find the same"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G1_PRENUMBER']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.ORDER_OBJECTS', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES', 'mathematics', 1, 'Order objects according to given criteria', ARRAY['MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.c']::text[], 'The child arranges three to five objects from smallest to biggest (or shortest to longest, lightest to heaviest) and the reverse, and names the first and last.', '["order from smallest to biggest","which comes first","which is out of order","order from biggest"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G1_PRENUMBER']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.OBJECT_PATTERNS', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES', 'mathematics', 1, 'Create patterns of different sizes and shapes using real objects', ARRAY['MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.d']::text[], 'The child copies, continues and makes a repeating pattern with real objects (bottle tops, leaves, beads) by colour, size or shape, and says what comes next.', '["what comes next","what is missing in the pattern","which part repeats","make a pattern"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G1_PRENUMBER']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_50', 'MATH.G1.NUMBER.WHOLE_NUMBERS', 'mathematics', 1, 'Count numbers forward up to 50', ARRAY['MATH.G1.NUMBER.WHOLE_NUMBERS.a', 'MATH.G1.NUMBER.WHOLE_NUMBERS.g']::text[], 'Starting from any number, the child counts on in ones to 50 (and in twos to 20), saying each number once, crossing each ten correctly (19, 20, 21), and says the number after any number.', '["count on from a number","what comes next","missing number in a forward count","count on in twos"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G1_COUNTING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.WHOLE_NUMBERS.COUNT_BACK_30', 'MATH.G1.NUMBER.WHOLE_NUMBERS', 'mathematics', 1, 'Count numbers backward from 30', ARRAY['MATH.G1.NUMBER.WHOLE_NUMBERS.b']::text[], 'The child counts back in ones from 30 or from any number up to 30, crossing each ten correctly (21, 20, 19), and says the number before.', '["count back from a number","what comes before","missing number in a backward count","count down to zero"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G1_COUNTING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.WHOLE_NUMBERS.REPRESENT_30', 'MATH.G1.NUMBER.WHOLE_NUMBERS', 'mathematics', 1, 'Represent numbers 1 to 30 using concrete objects', ARRAY['MATH.G1.NUMBER.WHOLE_NUMBERS.c']::text[], 'The child counts out a given number of objects up to 30, touching each once, and matches a group of objects to its number, keeping track by moving each object as it is counted.', '["count out this many","how many objects","match the group to the number","show the number with bottle tops"]'::jsonb, '["representation","procedure"]'::jsonb, ARRAY['G1_COUNTING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.WHOLE_NUMBERS.READ_WRITE_50', 'MATH.G1.NUMBER.WHOLE_NUMBERS', 'mathematics', 1, 'Read and write numbers 1 to 50 in symbols', ARRAY['MATH.G1.NUMBER.WHOLE_NUMBERS.d']::text[], 'The child reads any number up to 50 and writes numbers to 50 in symbols with digits facing the right way and in the right order (14, not 41).', '["write the number said","read the number","write the number of objects","which is written correctly"]'::jsonb, '["recall"]'::jsonb, ARRAY['G1_COUNTING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.WHOLE_NUMBERS.WORDS_10', 'MATH.G1.NUMBER.WHOLE_NUMBERS', 'mathematics', 1, 'Read and write numbers 1 to 10 in words', ARRAY['MATH.G1.NUMBER.WHOLE_NUMBERS.e']::text[], 'The child reads and writes the number words one to ten with correct spelling and matches each word to its numeral and to a group of objects.', '["write the number in words","match the word to the number","choose the right spelling","read the word"]'::jsonb, '["recall"]'::jsonb, ARRAY['G1_COUNTING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.WHOLE_NUMBERS.NUMBER_PATTERNS_20', 'MATH.G1.NUMBER.WHOLE_NUMBERS', 'mathematics', 1, 'Identify missing numbers in number patterns up to 20', ARRAY['MATH.G1.NUMBER.WHOLE_NUMBERS.f']::text[], 'The child finds the missing number in a counting pattern going up or down in ones or twos up to 20 (2, 4, __, 8), and says the jump. Counting in fives and tens is met in the older practice families.', '["missing number","next number","count in twos","what is the jump"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G1_COUNTING', 'G1_PRENUMBER']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.ADDITION.MODEL_ADDITION', 'MATH.G1.NUMBER.ADDITION', 'mathematics', 1, 'Model addition as putting objects together', ARRAY['MATH.G1.NUMBER.ADDITION.a']::text[], 'The child puts two groups of objects together and counts all of them to find how many there are now, and tells a ''had some, got some more'' story for it (3 birds and 2 more birds is 5 birds).', '["how many now","put together and count","a story with more coming","draw both groups"]'::jsonb, '["representation","procedure"]'::jsonb, ARRAY['G1_ADD']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.ADDITION.ADD_SIGNS', 'MATH.G1.NUMBER.ADDITION', 'mathematics', 1, 'Use the + and = signs in writing addition statements', ARRAY['MATH.G1.NUMBER.ADDITION.b']::text[], 'The child writes an addition statement for a picture or story with + and = in the right places (3 + 2 = 5) and reads it as ''three add two equals five''.', '["write the addition sentence","read the sentence","put in the missing sign","match the picture to the sentence"]'::jsonb, '["representation"]'::jsonb, ARRAY['G1_ADD']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.ADDITION.ADD_TWO_SINGLE', 'MATH.G1.NUMBER.ADDITION', 'mathematics', 1, 'Add two single-digit numbers', ARRAY['MATH.G1.NUMBER.ADDITION.c', 'MATH.G1.NUMBER.ADDITION.g']::text[], 'The child adds two single-digit numbers (7 + 5 = 12) by counting on from the larger, using fingers, objects or a number line, in stories and number sentences. Games with dice and devices are played in class.', '["add two numbers","count on from the bigger","a story with two amounts","roll two dice"]'::jsonb, '["procedure","recall"]'::jsonb, ARRAY['G1_ADD']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.ADDITION.ADD_THREE_SINGLE', 'MATH.G1.NUMBER.ADDITION', 'mathematics', 1, 'Add three single-digit numbers', ARRAY['MATH.G1.NUMBER.ADDITION.d']::text[], 'The child adds three single-digit numbers (4 + 3 + 5 = 12) by adding two first and then the third, or by finding a pair that makes ten.', '["add three numbers","a story with three amounts","make ten first","missing number of three"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G1_ADD']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.ADDITION.ADD_2D_1D_50', 'MATH.G1.NUMBER.ADDITION', 'mathematics', 1, 'Add a 2-digit number to a 1-digit number without regrouping, sum up to 50', ARRAY['MATH.G1.NUMBER.ADDITION.e']::text[], 'The child adds a 1-digit number to a 2-digit number when the ones do not make ten (23 + 4 = 27), across or in a column, using an abacus or number cards, with the sum up to 50.', '["column addition","horizontal addition","count on","a story with a total"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G1_ADD']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.ADDITION.ADD_MISSING_50', 'MATH.G1.NUMBER.ADDITION', 'mathematics', 1, 'Work out missing numbers in addition patterns up to 50', ARRAY['MATH.G1.NUMBER.ADDITION.f']::text[], 'The child finds the missing number in an adding pattern (5, 7, 9, __) or in an addition (6 + __ = 10, how many more are needed) by counting up from the number known.', '["missing number in a pattern","how many more are needed","6 + __ = 10","next number"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G1_ADD']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.MODEL_SUBTRACTION', 'MATH.G1.NUMBER.SUBTRACTION', 'mathematics', 1, 'Model subtraction as taking away using concrete objects', ARRAY['MATH.G1.NUMBER.SUBTRACTION.a']::text[], 'The child takes some objects away from a group and counts what is left (8 sweets, 3 given away, 5 left), and tells a ''had some, gave some away'' story for it.', '["how many are left","take away and count","a story of giving away","cross out and count"]'::jsonb, '["representation","procedure"]'::jsonb, ARRAY['G1_SUB']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.SUB_SIGNS', 'MATH.G1.NUMBER.SUBTRACTION', 'mathematics', 1, 'Use the - and = signs in writing subtraction sentences', ARRAY['MATH.G1.NUMBER.SUBTRACTION.b']::text[], 'The child writes a subtraction sentence for a picture or story with - and = in the right places, with the starting number first (8 - 3 = 5), and reads it.', '["write the subtraction sentence","read the sentence","put in the missing sign","match the picture to the sentence"]'::jsonb, '["representation"]'::jsonb, ARRAY['G1_SUB']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.SUB_SINGLE', 'MATH.G1.NUMBER.SUBTRACTION', 'mathematics', 1, 'Subtract single-digit numbers', ARRAY['MATH.G1.NUMBER.SUBTRACTION.c', 'MATH.G1.NUMBER.SUBTRACTION.f']::text[], 'The child takes a single-digit number from a number up to 18 (13 - 5 = 8) by counting back, using objects or a number line, or from a known addition fact (5 + 8 = 13). Games are played in class.', '["take away","count back","a giving-away story","use the addition fact"]'::jsonb, '["procedure","recall"]'::jsonb, ARRAY['G1_SUB']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.SUB_2D_1D_NO_REGROUP', 'MATH.G1.NUMBER.SUBTRACTION', 'mathematics', 1, 'Subtract a 1-digit number from a 2-digit number without regrouping', ARRAY['MATH.G1.NUMBER.SUBTRACTION.d']::text[], 'The child takes a 1-digit number from a 2-digit number when the ones digit is big enough (37 - 4 = 33), across or in a column, with number cards or a chart.', '["column subtraction","count back","how many are left","horizontal subtraction"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G1_SUB']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.SUB_MISSING_50', 'MATH.G1.NUMBER.SUBTRACTION', 'mathematics', 1, 'Work out missing numbers in subtraction patterns up to 50', ARRAY['MATH.G1.NUMBER.SUBTRACTION.e']::text[], 'The child continues or fills in a pattern that goes down by the same number (20, 18, 16, __) and finds a missing number in a subtraction (some were eaten, 5 are left from 12: how many were eaten?).', '["next number going down","missing term","how many were taken","12 - __ = 5"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G1_SUB']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.MEASUR.LENGTH.COMPARE_LENGTH', 'MATH.G1.MEASUR.LENGTH', 'mathematics', 1, 'Collect objects and compare their lengths: longer than, shorter than, same as', ARRAY['MATH.G1.MEASUR.LENGTH.a', 'MATH.G1.MEASUR.LENGTH.b']::text[], 'The child collects objects of different lengths, lines up one end of two objects, and says which is longer than, shorter than or the same as the other; finds the longest and shortest of three.', '["which is longer","which is shorter","are they the same length","the longest of three"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G1_LENGTH']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.MEASUR.LENGTH.MEASURE_ARBITRARY_LENGTH', 'MATH.G1.MEASUR.LENGTH', 'mathematics', 1, 'Measure length using arbitrary units', ARRAY['MATH.G1.MEASUR.LENGTH.c']::text[], 'The child measures a length with hand spans, steps, sticks or pencils laid end to end without gaps, counts the units, and says why two children''s hand-span counts for the same desk can differ.', '["how many hand spans long","how many steps across","why are the counts different","which unit gives more"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G1_LENGTH']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.MEASUR.MASS.COMPARE_MASS', 'MATH.G1.MEASUR.MASS', 'mathematics', 1, 'Collect objects and compare masses: heavier than, lighter than, same as', ARRAY['MATH.G1.MEASUR.MASS.a', 'MATH.G1.MEASUR.MASS.b']::text[], 'The child holds two objects and says which is heavier, lighter or about the same, and puts three objects in order from two comparisons (if the cow is heavier than the goat and the goat heavier than the hen, the cow is heaviest).', '["which is heavier","which is lighter","are they the same","the heaviest of three"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G1_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.MEASUR.MASS.MEASURE_ARBITRARY_MASS', 'MATH.G1.MEASUR.MASS', 'mathematics', 1, 'Measure mass using arbitrary units', ARRAY['MATH.G1.MEASUR.MASS.c']::text[], 'The child measures how many cups or tins of beans or maize balance an object, or how many tins of a known mass make a bag, and counts the units.', '["how many tins balance it","how many cups of beans","which needs more units","read the balance picture"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G1_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.MEASUR.CAPACITY.COMPARE_CAPACITY', 'MATH.G1.MEASUR.CAPACITY', 'mathematics', 1, 'Collect containers and compare capacity: more than, less than, same as', ARRAY['MATH.G1.MEASUR.CAPACITY.a', 'MATH.G1.MEASUR.CAPACITY.b', 'MATH.G1.MEASUR.CAPACITY.d']::text[], 'The child pours water from one container into another to say which holds more, less or the same, does not judge by height alone, and re-uses containers to keep items.', '["which holds more","which holds less","do they hold the same","fill and pour to check"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G1_CAPACITY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.MEASUR.CAPACITY.MEASURE_ARBITRARY_CAPACITY', 'MATH.G1.MEASUR.CAPACITY', 'mathematics', 1, 'Measure capacity using arbitrary units', ARRAY['MATH.G1.MEASUR.CAPACITY.c']::text[], 'The child fills a basin or jug with a small container (a cup, a tin), counts the full cups, and compares two containers by their cup counts.', '["how many cups fill it","which holds more cups","bigger cup, fewer cups","read the picture of cups"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G1_CAPACITY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.MEASUR.TIME.DAYS_OF_WEEK', 'MATH.G1.MEASUR.TIME', 'mathematics', 1, 'Identify the days of the week', ARRAY['MATH.G1.MEASUR.TIME.a']::text[], 'The child says and writes the seven days of the week in order starting from any day, says which day comes before and after a given day, and counts on days (in 3 days from Monday it is Thursday), using today, yesterday and tomorrow.', '["the day after","the day before","in 2 days it will be","put the days in order"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G1_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.MEASUR.TIME.DAYS_ACTIVITIES', 'MATH.G1.MEASUR.TIME', 'mathematics', 1, 'Relate days of the week to various activities', ARRAY['MATH.G1.MEASUR.TIME.b']::text[], 'The child names what happens on particular days (raising the flag on Monday and Friday, no school on Saturday and Sunday, church or mosque day, market day) and says the day for an activity.', '["which day is this activity","what do we do on Monday","school days and weekend days","order the week''s activities"]'::jsonb, '["recall"]'::jsonb, ARRAY['G1_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.MEASUR.TIME.MONTHS_OF_YEAR', 'MATH.G1.MEASUR.TIME', 'mathematics', 1, 'Identify the months of the year', ARRAY['MATH.G1.MEASUR.TIME.c']::text[], 'The child says the twelve months in order (with a song), names the month of their birthday, and says which month comes before and after a given month.', '["the month after","the month before","your birth month","put the months in order"]'::jsonb, '["recall"]'::jsonb, ARRAY['G1_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.MEASUR.MONEY.IDENTIFY_COINS', 'MATH.G1.MEASUR.MONEY', 'mathematics', 1, 'Identify Kenyan currency coins', ARRAY['MATH.G1.MEASUR.MONEY.a']::text[], 'The child names the Kenyan coins (sh. 1, sh. 5, sh. 10, sh. 20) by the number on them, sorts coins by value, and says which of two coins is worth more.', '["name the coin","sort coins by value","which coin is worth more","find the sh. 10 coin"]'::jsonb, '["recall"]'::jsonb, ARRAY['G1_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.MEASUR.MONEY.IDENTIFY_50_NOTE', 'MATH.G1.MEASUR.MONEY', 'mathematics', 1, 'Identify the sh. 50 Kenyan currency note', ARRAY['MATH.G1.MEASUR.MONEY.b']::text[], 'The child recognises the sh. 50 note, says its value, and tells it from the coins.', '["which is the sh. 50 note","what is this note worth","note or coin","is the note worth more than a sh. 20 coin"]'::jsonb, '["recall"]'::jsonb, ARRAY['G1_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.MEASUR.MONEY.COUNT_COINS', 'MATH.G1.MEASUR.MONEY', 'mathematics', 1, 'Count Kenyan currency coins one at a time', ARRAY['MATH.G1.MEASUR.MONEY.c']::text[], 'The child counts coins of one kind and then a mix (two sh. 10 coins and one sh. 5 coin is sh. 25) by counting on the value of each coin, and says how many coins there are and how much they are worth as two different things.', '["how much money","how many coins","count ten-shilling coins","count a mix of coins"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G1_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.MEASUR.MONEY.BUY_TWO_ITEMS', 'MATH.G1.MEASUR.MONEY', 'mathematics', 1, 'Use money to buy up to 2 items without balance', ARRAY['MATH.G1.MEASUR.MONEY.d']::text[], 'The child finds the cost of up to 2 items in a model shop (total up to sh. 50) and picks coins or the note that pay exactly, with no change.', '["total cost of two items","which coins pay exactly","is the money enough","role play at the shop"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G1_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.GEOMET.LINES.IDENTIFY_LINES', 'MATH.G1.GEOMET.LINES', 'mathematics', 1, 'Identify straight and curved lines in different situations and objects', ARRAY['MATH.G1.GEOMET.LINES.a', 'MATH.G1.GEOMET.LINES.c', 'MATH.G1.GEOMET.LINES.e']::text[], 'The child says whether a line or an edge is straight or curved (a queue of children, the edge of a door, a semicircle, the rim of a plate) and finds straight and curved lines in real objects.', '["straight or curved","which edge is curved","find a straight line in the picture","sort lines"]'::jsonb, '["recall"]'::jsonb, ARRAY['G1_LINES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.GEOMET.LINES.DRAW_LINES', 'MATH.G1.GEOMET.LINES', 'mathematics', 1, 'Draw straight and curved lines on different surfaces', ARRAY['MATH.G1.GEOMET.LINES.b', 'MATH.G1.GEOMET.LINES.d']::text[], 'The child draws straight lines by joining two points with a stick or ruler, and curved lines freehand, on the ground and in books.', '[]'::jsonb, '["representation"]'::jsonb, ARRAY['G1_LINES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.GEOMET.SHAPES.IDENTIFY_SHAPES', 'MATH.G1.GEOMET.SHAPES', 'mathematics', 1, 'Identify rectangles, triangles and circles in objects from the environment', ARRAY['MATH.G1.GEOMET.SHAPES.a']::text[], 'The child names rectangles, triangles and circles in objects and pictures (a door, a roof, a clock), in any position, by their sides and corners (a triangle has 3 sides and 3 corners; a circle has none).', '["name the shape","which object is a circle","how many sides","pick the shape with 3 corners"]'::jsonb, '["recall"]'::jsonb, ARRAY['G1_SHAPES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G1.GEOMET.SHAPES.SHAPE_PATTERNS_1', 'MATH.G1.GEOMET.SHAPES', 'mathematics', 1, 'Make patterns involving rectangles, triangles, circles and ovals', ARRAY['MATH.G1.GEOMET.SHAPES.b']::text[], 'The child copies, continues and makes a repeating pattern of shapes (circle, triangle, circle, triangle) and says which shape comes next.', '["what comes next","what is missing","which part repeats","make a shape pattern"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G1_SHAPES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
