INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.SORT_OBJECTS.M_SORT_TWO_RULES', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.SORT_OBJECTS', 'Changes the rule part way, sorting some by colour and some by size.', '{"question":"Sort these by colour: a big red ball, a small red ball, a big blue ball. Which go together?","wrong_answer":"the two big balls","correct_answer":"the two red balls"}'::jsonb, 'Starts with one rule and switches.', 'The answer the two big balls as a wrong option, with a reason that names the idea.', 'Say the rule aloud before each object.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.SORT_OBJECTS.M_SORT_ODD_ONE', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.SORT_OBJECTS', 'Cannot say which object does not belong.', '{"question":"A spoon, a fork, a cup and a stone. Which does not belong with things for eating?","wrong_answer":"the cup","correct_answer":"the stone"}'::jsonb, 'Looks at shape, not use.', 'The answer the cup as a wrong option, with a reason that names the idea.', 'Ask: what do we use each one for?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.SORT_OBJECTS.M_SORT_NO_RULE', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.SORT_OBJECTS', 'Groups objects with no rule and cannot say why.', '{"question":"Why did you put the leaf with the bottle top?","wrong_answer":"I wanted to","correct_answer":"they are both green"}'::jsonb, 'Sorts by liking or at random.', 'The answer I wanted to as a wrong option, with a reason that names the idea.', 'Name what is the same about the group.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.SORT_OBJECTS.M_SORT_ONE_GROUP_MISSED', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.SORT_OBJECTS', 'Leaves out objects that fit the rule.', '{"question":"Put all the round things together: a ball, an orange, a plate, a box.","wrong_answer":"the ball and the orange","correct_answer":"the ball, the orange and the plate"}'::jsonb, 'Stops before checking every object.', 'The answer the ball and the orange as a wrong option, with a reason that names the idea.', 'Check each object against the rule.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.MATCH_OBJECTS.M_MATCH_COLOUR_ONLY', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.MATCH_OBJECTS', 'Matches by colour when asked to match by use.', '{"question":"Match by use: a cup goes with a saucer or a red ball?","wrong_answer":"the red ball (same colour)","correct_answer":"the saucer"}'::jsonb, 'Looks at colour first.', 'The answer the red ball (same colour) as a wrong option, with a reason that names the idea.', 'Ask what each is used for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.MATCH_OBJECTS.M_MATCH_SIZE_MISS', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.MATCH_OBJECTS', 'Matches objects of the same kind but different sizes when asked for the same size.', '{"question":"Match the same size: a big stone with a small stone or a big stone?","wrong_answer":"the small stone","correct_answer":"the big stone"}'::jsonb, 'Matches the kind, not the size.', 'The answer the small stone as a wrong option, with a reason that names the idea.', 'Place them side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.MATCH_OBJECTS.M_MATCH_EXTRA', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.MATCH_OBJECTS', 'Leaves one object with no partner and does not notice.', '{"question":"Pair the shoes: 7 shoes. Are all paired?","wrong_answer":"yes","correct_answer":"no, one is left"}'::jsonb, 'Does not check each one has a pair.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Count the pairs and see what is left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.MATCH_OBJECTS.M_MATCH_CANNOT_SAY_WHY', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.MATCH_OBJECTS', 'Matches but cannot give the shared attribute.', '{"question":"Why do the two leaves match?","wrong_answer":"they match","correct_answer":"both are long and green"}'::jsonb, 'Has not named the attribute.', 'The answer they match as a wrong option, with a reason that names the idea.', 'Say: they are both ...', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.ORDER_OBJECTS.M_ORD1_REVERSED', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.ORDER_OBJECTS', 'Orders from biggest to smallest when asked smallest first.', '{"question":"Order from smallest: a mango, a grape, a pumpkin.","wrong_answer":"pumpkin, mango, grape","correct_answer":"grape, mango, pumpkin"}'::jsonb, 'Ignores the direction word.', 'The answer pumpkin, mango, grape as a wrong option, with a reason that names the idea.', 'Point to the start: smallest first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.ORDER_OBJECTS.M_ORD1_MIDDLE', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.ORDER_OBJECTS', 'Puts the ends right but the middle wrong.', '{"question":"Order from shortest: sticks of 3, 7, 5 and 9 hand spans.","wrong_answer":"3, 7, 5, 9","correct_answer":"3, 5, 7, 9"}'::jsonb, 'Compares only with the ends.', 'The answer 3, 7, 5, 9 as a wrong option, with a reason that names the idea.', 'Take the smallest of those left each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.ORDER_OBJECTS.M_ORD1_NOT_ALIGNED', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.ORDER_OBJECTS', 'Compares lengths without lining up one end.', '{"question":"Two pencils: one sticks out further but starts higher. Which is longer?","wrong_answer":"the one that sticks out","correct_answer":"the one that is longer end to end"}'::jsonb, 'Looks only at one end.', 'The answer the one that sticks out as a wrong option, with a reason that names the idea.', 'Line up one end first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.ORDER_OBJECTS.M_ORD1_SIZE_HEIGHT_MIX', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.ORDER_OBJECTS', 'Orders by height when asked for heaviness.', '{"question":"Order from lightest: a tall empty box, a small stone, a feather.","wrong_answer":"feather, stone, box","correct_answer":"feather, box, stone"}'::jsonb, 'Uses size for every comparison.', 'The answer feather, stone, box as a wrong option, with a reason that names the idea.', 'Hold each: which is heavier?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.OBJECT_PATTERNS.M_OPAT_REPEATS_LAST', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.OBJECT_PATTERNS', 'Repeats the last object instead of the pattern.', '{"question":"red, blue, red, blue, red, __","wrong_answer":"red","correct_answer":"blue"}'::jsonb, 'Copies the last one.', 'The answer red as a wrong option, with a reason that names the idea.', 'Say the pattern aloud from the start.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
