INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.ADDITION.MODEL_ADDITION.M_ADD1_COUNTS_START_AGAIN', 'MATH.G1.NUMBER.ADDITION.MODEL_ADDITION', 'When counting on, counts the start number again, so the answer is one less.', '{"question":"There are 6 birds. 3 more fly in. How many now?","wrong_answer":"8","correct_answer":"9"}'::jsonb, 'Says the first number as ''one'' when counting on.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'Hold 6 in your head; count 7, 8, 9 on fingers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
