INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.ADDITION.MODEL_ADDITION.M_ADD1_GIVES_START', 'MATH.G1.NUMBER.ADDITION.MODEL_ADDITION', 'Gives the starting number as the answer.', '{"question":"There are 7 birds. 2 more fly in. How many now?","wrong_answer":"7","correct_answer":"9"}'::jsonb, 'Stops at the first group.', 'The answer 7 as a wrong option, with a reason that names the idea.', 'Count both groups.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
