INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.ADDITION.ADD_SIGNS.M_SIGN1_EQUALS_FIRST', 'MATH.G1.NUMBER.ADDITION.ADD_SIGNS', 'Puts = before the numbers, as = 3 + 2 5.', '{"question":"Write 3 and 2 make 5.","wrong_answer":"= 3 + 2 5","correct_answer":"3 + 2 = 5"}'::jsonb, 'Does not know where = goes.', 'The answer = 3 + 2 5 as a wrong option, with a reason that names the idea.', 'The = comes just before the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
