INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.ADDITION.ADD_MISSING_50.M_AMISS1_PATTERN_ONE', 'MATH.G1.NUMBER.ADDITION.ADD_MISSING_50', 'Adds one in a pattern that goes up by two.', '{"question":"5, 7, 9, __","wrong_answer":"10","correct_answer":"11"}'::jsonb, 'Assumes a jump of one.', 'The answer 10 as a wrong option, with a reason that names the idea.', 'Find the jump between two numbers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.MODEL_SUBTRACTION.M_SUB1_COUNTS_START', 'MATH.G1.NUMBER.SUBTRACTION.MODEL_SUBTRACTION', 'Counts back including the starting number, so the answer is one more.', '{"question":"Juma has 9 sweets and gives 3 away. How many are left?","wrong_answer":"7","correct_answer":"6"}'::jsonb, 'Says 9 as the first count back.', 'The answer 7 as a wrong option, with a reason that names the idea.', 'Finger on 9; count back 8, 7, 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.MODEL_SUBTRACTION.M_SUB1_ADDS', 'MATH.G1.NUMBER.SUBTRACTION.MODEL_SUBTRACTION', 'Adds when some are given away.', '{"question":"Juma has 9 sweets and gives 3 away. How many are left?","wrong_answer":"12","correct_answer":"6"}'::jsonb, 'Sees two numbers and adds.', 'The answer 12 as a wrong option, with a reason that names the idea.', 'Giving away makes fewer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.MODEL_SUBTRACTION.M_SUB1_GIVES_TAKEN', 'MATH.G1.NUMBER.SUBTRACTION.MODEL_SUBTRACTION', 'Gives the number taken away as the answer.', '{"question":"Amina has 8 pencils and gives 3 away. How many are left?","wrong_answer":"3","correct_answer":"5"}'::jsonb, 'Repeats a number from the story.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'Cross out the ones given and count the rest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.MODEL_SUBTRACTION.M_SUB1_TAKES_WRONG_NUMBER', 'MATH.G1.NUMBER.SUBTRACTION.MODEL_SUBTRACTION', 'Takes away one too many or too few objects.', '{"question":"Take 4 away from 10 stones. How many are left?","wrong_answer":"5","correct_answer":"6"}'::jsonb, 'Does not count the ones taken.', 'The answer 5 as a wrong option, with a reason that names the idea.', 'Count each stone as you take it away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.SUB_SIGNS.M_SSIGN_SMALL_FIRST', 'MATH.G1.NUMBER.SUBTRACTION.SUB_SIGNS', 'Writes the smaller number first, as 3 - 8 = 5.', '{"question":"Write: 8 take away 3 is 5.","wrong_answer":"3 - 8 = 5","correct_answer":"8 - 3 = 5"}'::jsonb, 'Writes the numbers in any order.', 'The answer 3 - 8 = 5 as a wrong option, with a reason that names the idea.', 'Start with how many there were.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.SUB_SIGNS.M_SSIGN_PLUS', 'MATH.G1.NUMBER.SUBTRACTION.SUB_SIGNS', 'Writes + for a taking-away story.', '{"question":"Write: 7 birds, 2 fly away, 5 left.","wrong_answer":"7 + 2 = 5","correct_answer":"7 - 2 = 5"}'::jsonb, 'Mixes the signs.', 'The answer 7 + 2 = 5 as a wrong option, with a reason that names the idea.', '- means take away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.SUB_SIGNS.M_SSIGN_EQUALS_PLACE', 'MATH.G1.NUMBER.SUBTRACTION.SUB_SIGNS', 'Puts = in the wrong place, as 8 = 3 - 5.', '{"question":"Write 8 take away 3 equals 5.","wrong_answer":"8 = 3 - 5","correct_answer":"8 - 3 = 5"}'::jsonb, 'Does not know where = goes.', 'The answer 8 = 3 - 5 as a wrong option, with a reason that names the idea.', '= goes just before the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.SUB_SIGNS.M_SSIGN_PICTURE_MISMATCH', 'MATH.G1.NUMBER.SUBTRACTION.SUB_SIGNS', 'Writes numbers that do not match the picture.', '{"question":"A picture: 6 mangoes, 2 crossed out. Write the sentence.","wrong_answer":"6 - 4 = 2","correct_answer":"6 - 2 = 4"}'::jsonb, 'Uses the number left as the number taken.', 'The answer 6 - 4 = 2 as a wrong option, with a reason that names the idea.', 'Count the crossed-out ones: that is taken away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.SUB_SINGLE.M_SS_COUNTS_START', 'MATH.G1.NUMBER.SUBTRACTION.SUB_SINGLE', 'Counts back including the start number.', '{"question":"13 - 5","wrong_answer":"9","correct_answer":"8"}'::jsonb, 'Says 13 as a step.', 'The answer 9 as a wrong option, with a reason that names the idea.', 'Finger on 13: 12, 11, 10, 9, 8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
