INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.SUB_SINGLE.M_SS_FACT_WRONG_PART', 'MATH.G1.NUMBER.SUBTRACTION.SUB_SINGLE', 'Uses the addition fact but gives the wrong part.', '{"question":"5 + 8 = 13, so 13 - 5 = ?","wrong_answer":"13","correct_answer":"8"}'::jsonb, 'Repeats the total.', 'The answer 13 as a wrong option, with a reason that names the idea.', 'Take the 5 away from 5 + 8: what is left?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
