INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.NUMBER.SUBTRACTION.SUB_2D_1D_NO_REGROUP.M_S21_1_COUNTS_START', 'MATH.G1.NUMBER.SUBTRACTION.SUB_2D_1D_NO_REGROUP', 'Counts back including the start number.', '{"question":"46 - 3, counting back","wrong_answer":"44","correct_answer":"43"}'::jsonb, 'Says 46 as a step.', 'The answer 44 as a wrong option, with a reason that names the idea.', 'Finger on 46: 45, 44, 43.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
