INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.MEASUR.LENGTH.COMPARE_LENGTH.M_CL1_NOT_ALIGNED', 'MATH.G1.MEASUR.LENGTH.COMPARE_LENGTH', 'Compares without lining up the ends.', '{"question":"Two sticks: the shorter one starts further along so its end is further right. Which is longer?","wrong_answer":"the one that ends further right","correct_answer":"the one longer from end to end"}'::jsonb, 'Looks at one end only.', 'The answer the one that ends further right as a wrong option, with a reason that names the idea.', 'Line up one end, then look at the other end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
