INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.MEASUR.LENGTH.COMPARE_LENGTH.M_CL1_LONGER_SHORTER_SWAP', 'MATH.G1.MEASUR.LENGTH.COMPARE_LENGTH', 'Uses longer when shorter is meant.', '{"question":"A pencil is shorter than a ruler. Which is longer?","wrong_answer":"the pencil","correct_answer":"the ruler"}'::jsonb, 'Mixes the words.', 'The answer the pencil as a wrong option, with a reason that names the idea.', 'Act it: stretch arms for longer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.MEASUR.LENGTH.COMPARE_LENGTH.M_CL1_BENT_STRING', 'MATH.G1.MEASUR.LENGTH.COMPARE_LENGTH', 'Thinks a curled string is shorter than a straight one of the same length.', '{"question":"Two equal strings, one curled up. Is the curled one shorter?","wrong_answer":"yes","correct_answer":"no, the same"}'::jsonb, 'Judges by how far the ends reach.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Straighten the string and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.MEASUR.LENGTH.MEASURE_ARBITRARY_LENGTH.M_MAL_GAPS', 'MATH.G1.MEASUR.LENGTH.MEASURE_ARBITRARY_LENGTH', 'Leaves gaps between hand spans or steps.', '{"question":"Hand spans with gaps between count 6 along a desk. Is it 6 spans long?","wrong_answer":"yes","correct_answer":"no, more"}'::jsonb, 'Does not put each span where the last ended.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Put the thumb where the little finger was.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G1.MEASUR.LENGTH.MEASURE_ARBITRARY_LENGTH.M_MAL_UNIT_SIZE', 'MATH.G1.MEASUR.LENGTH.MEASURE_ARBITRARY_LENGTH', 'Thinks a bigger hand span gives a bigger count.', '{"question":"Teacher''s span and a child''s span measure the same table. Who counts more spans?","wrong_answer":"the teacher","correct_answer":"the child"}'::jsonb, 'Bigger unit, bigger number.', 'The answer the teacher as a wrong option, with a reason that names the idea.', 'Try both and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
